toolArgs.file_text:
/* =============================================
   Chat Page Layout
   ============================================= */

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* ---- Channel Sidebar ---- */

.channel-sidebar {
    width: 260px;
    min-width: 200px;
    background: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #202225;
}

.sidebar-header h5 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 1px 8px;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #36393f;
}

.channel-item.active {
    background: #393c43;
    color: #fff;
}

.channel-name-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

.channel-item.active .channel-name {
    font-weight: 700;
}

.unread-badge {
    background: #ed4245;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 1px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

.channel-description {
    font-size: 0.75rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ---- Message Area ---- */

.message-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #36393f;
    color: #dcddde;
    min-width: 0;
}

.message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #202225;
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-shrink: 0;
}

.message-area-header h4 {
    margin: 0;
    color: #fff;
    font-size: 1.1rem;
    font-weight: 700;
    white-space: nowrap;
}

.channel-desc-text {
    font-size: 0.85rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    color: #8e9297;
    font-size: 0.85rem;
}

/* ---- Message Item ---- */

.message-item {
    position: relative;
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

.message-item:hover {
    background: #32353b;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.message-author {
    font-weight: 600;
    color: #fff;
    font-size: 0.95rem;
}

.message-time {
    font-size: 0.75rem;
    color: #72767d;
}

.message-content {
    font-size: 0.95rem;
    line-height: 1.4;
    word-break: break-word;
}

/* Reactions */

.reaction-bar {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 6px;
}

.reaction-badge {
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    color: #dcddde;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #40444b;
    border-color: #5865f2;
}

/* Thread link */

.thread-link {
    background: none;
    border: none;
    color: #5865f2;
    font-size: 0.8rem;
    font-weight: 500;
    cursor: pointer;
    padding: 4px 0;
    margin-top: 4px;
}

.thread-link:hover {
    text-decoration: underline;
}

/* Hover actions */

.message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 4px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
    z-index: 10;
}

.action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 3px;
    font-size: 0.8rem;
    white-space: nowrap;
}

.action-btn:hover {
    background: #40444b;
    color: #fff;
}

/* Emoji picker */

.emoji-picker {
    position: absolute;
    top: -8px;
    right: 160px;
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #4f545c;
    border-radius: 6px;
    padding: 6px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
    z-index: 11;
}

.emoji-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-btn:hover {
    background: #40444b;
}

/* ---- Message Input ---- */

.message-input {
    padding: 12px 20px;
    border-top: 1px solid #202225;
    display: flex;
    gap: 8px;
    align-items: flex-end;
    flex-shrink: 0;
}

.message-textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    color: #dcddde;
    padding: 10px 14px;
    font-size: 0.95rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

.message-textarea::placeholder {
    color: #72767d;
}

.message-textarea:focus {
    box-shadow: 0 0 0 2px #5865f2;
}

.btn-send {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s;
    white-space: nowrap;
}

.btn-send:hover:not(:disabled) {
    background: #4752c4;
}

.btn-send:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* ---- Thread Panel ---- */

.thread-panel {
    width: 340px;
    min-width: 280px;
    background: #2f3136;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #202225;
}

.thread-header {
    padding: 12px 16px;
    border-bottom: 1px solid #202225;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-shrink: 0;
}

.thread-header h5 {
    margin: 0;
    color: #fff;
    font-size: 1rem;
    font-weight: 700;
}

.btn-close-thread {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

.btn-close-thread:hover {
    background: #40444b;
    color: #fff;
}

.thread-root-message {
    padding: 12px 16px;
    background: #36393f;
    margin: 12px;
    border-radius: 6px;
    border-left: 3px solid #5865f2;
}

.thread-divider {
    padding: 4px 16px;
    font-size: 0.75rem;
    color: #8e9297;
    border-bottom: 1px solid #40444b;
    margin: 0 12px;
    text-align: center;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 12px;
}

.thread-reply-item {
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 4px;
}

.thread-reply-item:hover {
    background: #36393f;
}

/* ---- Scrollbar Styling ---- */

.channel-list::-webkit-scrollbar,
.message-list::-webkit-scrollbar,
.thread-replies::-webkit-scrollbar {
    width: 6px;
}

.channel-list::-webkit-scrollbar-thumb,
.message-list::-webkit-scrollbar-thumb,
.thread-replies::-webkit-scrollbar-thumb {
    background: #202225;
    border-radius: 3px;
}

.channel-list::-webkit-scrollbar-track,
.message-list::-webkit-scrollbar-track,
.thread-replies::-webkit-scrollbar-track {
    background: transparent;
}

