arguments.new_str:
@page "/chat"
@namespace sv_feaea8c63d4a48f68dc4c06a540bca76.Components.Pages.Chat
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IChatService ChatService
@inject IJSRuntime JS

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannel?.Id"
                    OnChannelSelected="SelectChannel" />

    <MessageArea @ref="messageAreaRef"
                 ChannelName="@(selectedChannel?.Name ?? "Select a channel")"
                 ChannelDescription="@selectedChannel?.Description"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage" />

    @if (threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private bool isLoadingMore;
    private int skip;
    private const int PageSize = 30;
    private bool hasMoreMessages = true;

    // Thread state
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    // Component/JS references
    private MessageArea? messageAreaRef;
    private IJSObjectReference? jsModule;
    private DotNetObjectReference<ChatPage>? dotNetRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            jsModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Pages/Chat/ChatPage.razor.js");
            dotNetRef = DotNetObjectReference.Create(this);

            if (messageAreaRef is not null)
            {
                await jsModule.InvokeVoidAsync("registerScrollHandler",
                    messageAreaRef.MessageListRef, dotNetRef);
                await jsModule.InvokeVoidAsync("scrollToBottom",
                    messageAreaRef.MessageListRef);
            }
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        await LoadMoreMessages();
        await InvokeAsync(StateHasChanged);
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannel = channel;
        skip = 0;
        hasMoreMessages = true;
        messages = await ChatService.GetMessagesAsync(channel.Id, skip, PageSize);
        skip = messages.Count;
        BuildThreadSummaries();
