        // Refresh channels to update unread counts
        channels = await ChatService.GetChannelsAsync();

        // Close any open thread when switching channels
        threadRootMessage = null;
        threadReplies = [];

        // Re-register scroll handler and scroll to bottom for new channel
        if (jsModule is not null && messageAreaRef is not null)
        {
            await InvokeAsync(StateHasChanged);
            await jsModule.InvokeVoidAsync("registerScrollHandler",
                messageAreaRef.MessageListRef, dotNetRef);
            await jsModule.InvokeVoidAsync("scrollToBottom",
                messageAreaRef.MessageListRef);
        }
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || selectedChannel is null || !hasMoreMessages) return;

        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, skip, PageSize);
        if (older.Count < PageSize) hasMoreMessages = false;
        messages.InsertRange(0, older);
        skip += older.Count;
        BuildThreadSummaries();
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(msg);

        // Scroll to bottom after sending
        if (jsModule is not null && messageAreaRef is not null)
        {
            await InvokeAsync(StateHasChanged);
            await jsModule.InvokeVoidAsync("scrollToBottom",
                messageAreaRef.MessageListRef);
        }
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh messages to show updated reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, skip);
        }
    }

    private async Task OpenThread(int rootMessageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (threadRootMessage is null) return;

        var thread = await ChatService.GetThreadAsync(rootMessageId);
        threadReplies = thread.Where(m => m.Id != rootMessageId).ToList();
    }

    private void CloseThread()
    {
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || selectedChannel is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        BuildThreadSummaries();
    }

    private void BuildThreadSummaries()
    {
        var rootIds = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
        threadSummaries = rootIds;
    }

    public async ValueTask DisposeAsync()
    {
        dotNetRef?.Dispose();
        if (jsModule is not null)
        {
            await jsModule.DisposeAsync();
        }
    }
}

